sys_script.script:
(function executeRule(current, previous) {
  if (!current.student_name || current.student_name.nil()) {
    gs.addErrorMessage('Student Name is required.');
    current.setAbortAction(true);
    return;
  }
  if (!current.email || current.email.nil()) {
    gs.addErrorMessage('Email is required.');
    current.setAbortAction(true);
    return;
  }
  // Validate email format
  var emailStr = (current.email + '').trim();
  var emailRegex = /^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+.[A-Za-z]{2,}$/;
  if (!emailRegex.test(emailStr)) {
    gs.addErrorMessage('Invalid email format: ' + emailStr);
    current.setAbortAction(true);
    return;
  }
  // Validate CGPA / Percentage
  var cgpa = parseFloat(current.cgpa);
  if (!isNaN(cgpa) && (cgpa < 0 || cgpa > 100)) {
    gs.addErrorMessage('Academic CGPA or Percentage must be within valid range (0-10 or 0-100).');
    current.setAbortAction(true);
    return;
  }
  // Validate Income
  var income = parseFloat(current.annual_family_income);
  if (!isNaN(income) && income < 0) {
    gs.addErrorMessage('Annual family income cannot be negative.');
    current.setAbortAction(true);
    return;
  }
  // Prevent duplicate registration with same email
  var dupCheck = new GlideRecord('x_2200409_schola_1_student');
  dupCheck.addQuery('email', emailStr);
  if (!current.isNewRecord()) {
    dupCheck.addQuery('sys_id', '!=', current.getUniqueValue());
  }
  dupCheck.query();
  if (dupCheck.hasNext()) {
    gs.addErrorMessage('A student with email ' + emailStr + ' is already registered.');
    current.setAbortAction(true);
    return;
  }
  // Ensure student_status is active by default
  if (!current.student_status || current.student_status.nil()) {
    current.student_status = 'active';
  }
})(current, previous);
